-- mistri store layout: workflows, sqlite, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
CREATE TABLE "__mistri_workflow_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton=1),
  version INTEGER NOT NULL CHECK (version=1)
);
CREATE TABLE "__mistri_workflow_instance" (
  id TEXT COLLATE BINARY NOT NULL CHECK (typeof(id)='text' AND instr(id,char(0))=0 AND length(CAST(id AS BLOB)) BETWEEN 1 AND 36) PRIMARY KEY,
  workflow TEXT COLLATE BINARY NOT NULL CHECK (typeof(workflow)='text' AND instr(workflow,char(0))=0 AND length(CAST(workflow AS BLOB)) BETWEEN 1 AND 128),
  version INTEGER NOT NULL CHECK (typeof(version)='integer' AND version>=1),
  key TEXT COLLATE BINARY NOT NULL CHECK (typeof(key)='text' AND instr(key,char(0))=0 AND length(CAST(key AS BLOB)) BETWEEN 1 AND 512),
  state TEXT NOT NULL CHECK (state IN ('running','waiting','completed','failed','diverged','cancelled')),
  epoch INTEGER NOT NULL CHECK (typeof(epoch)='integer' AND epoch>=0),
  start_event_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(start_event_id)='text' AND instr(start_event_id,char(0))=0 AND length(CAST(start_event_id AS BLOB)) BETWEEN 1 AND 128),
  start_json TEXT COLLATE BINARY NOT NULL CHECK (typeof(start_json)='text' AND instr(start_json,char(0))=0 AND length(CAST(start_json AS BLOB)) BETWEEN 1 AND 65536),
  signal_floor INTEGER NOT NULL CHECK (typeof(signal_floor)='integer' AND signal_floor>=0),
  wait_event TEXT COLLATE BINARY CHECK (wait_event IS NULL OR (typeof(wait_event)='text' AND instr(wait_event,char(0))=0 AND length(CAST(wait_event AS BLOB)) BETWEEN 1 AND 256)),
  wake_at INTEGER CHECK (wake_at IS NULL OR (typeof(wake_at)='integer' AND wake_at>=0)),
  current_step TEXT COLLATE BINARY CHECK (current_step IS NULL OR (typeof(current_step)='text' AND instr(current_step,char(0))=0 AND length(CAST(current_step AS BLOB)) BETWEEN 1 AND 256)),
  problem TEXT COLLATE BINARY CHECK (problem IS NULL OR (typeof(problem)='text' AND instr(problem,char(0))=0 AND length(CAST(problem AS BLOB)) BETWEEN 1 AND 128)),
  problem_step TEXT COLLATE BINARY CHECK (problem_step IS NULL OR (typeof(problem_step)='text' AND instr(problem_step,char(0))=0 AND length(CAST(problem_step AS BLOB)) BETWEEN 1 AND 256)),
  problem_json TEXT COLLATE BINARY CHECK (problem_json IS NULL OR (typeof(problem_json)='text' AND instr(problem_json,char(0))=0 AND length(CAST(problem_json AS BLOB)) BETWEEN 1 AND 4096)),
  result_json TEXT COLLATE BINARY CHECK (result_json IS NULL OR (typeof(result_json)='text' AND instr(result_json,char(0))=0 AND length(CAST(result_json AS BLOB)) BETWEEN 1 AND 65536)),
  created_at INTEGER NOT NULL CHECK (typeof(created_at)='integer' AND created_at>=0),
  updated_at INTEGER NOT NULL CHECK (typeof(updated_at)='integer' AND updated_at>=0),
  UNIQUE (workflow,start_event_id)
);
CREATE TABLE "__mistri_workflow_step" (
  instance_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(instance_id)='text' AND instr(instance_id,char(0))=0 AND length(CAST(instance_id AS BLOB)) BETWEEN 1 AND 36) REFERENCES "__mistri_workflow_instance" (id) ON DELETE CASCADE,
  name TEXT COLLATE BINARY NOT NULL CHECK (typeof(name)='text' AND instr(name,char(0))=0 AND length(CAST(name AS BLOB)) BETWEEN 1 AND 256),
  ordinal INTEGER NOT NULL CHECK (typeof(ordinal)='integer' AND ordinal>=0),
  kind TEXT NOT NULL CHECK (kind IN ('run','call','sleep','until','waitFor','now')),
  hash TEXT COLLATE BINARY NOT NULL CHECK (typeof(hash)='text' AND instr(hash,char(0))=0 AND length(CAST(hash AS BLOB)) BETWEEN 1 AND 64),
  status TEXT NOT NULL CHECK (status IN ('pending','completed','refused','failed')),
  attempts INTEGER NOT NULL CHECK (typeof(attempts)='integer' AND attempts>=0),
  wake_at INTEGER CHECK (wake_at IS NULL OR (typeof(wake_at)='integer' AND wake_at>=0)),
  result_json TEXT COLLATE BINARY CHECK (result_json IS NULL OR (typeof(result_json)='text' AND instr(result_json,char(0))=0 AND length(CAST(result_json AS BLOB)) BETWEEN 1 AND 65536)),
  event_id TEXT COLLATE BINARY CHECK (event_id IS NULL OR (typeof(event_id)='text' AND instr(event_id,char(0))=0 AND length(CAST(event_id AS BLOB)) BETWEEN 1 AND 128)),
  error_code TEXT COLLATE BINARY CHECK (error_code IS NULL OR (typeof(error_code)='text' AND instr(error_code,char(0))=0 AND length(CAST(error_code AS BLOB)) BETWEEN 1 AND 128)),
  created_at INTEGER NOT NULL CHECK (typeof(created_at)='integer' AND created_at>=0),
  updated_at INTEGER NOT NULL CHECK (typeof(updated_at)='integer' AND updated_at>=0),
  PRIMARY KEY (instance_id,name)
);
CREATE TABLE "__mistri_workflow_signal" (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  workflow TEXT COLLATE BINARY NOT NULL CHECK (typeof(workflow)='text' AND instr(workflow,char(0))=0 AND length(CAST(workflow AS BLOB)) BETWEEN 1 AND 128),
  event_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(event_id)='text' AND instr(event_id,char(0))=0 AND length(CAST(event_id AS BLOB)) BETWEEN 1 AND 128),
  name TEXT COLLATE BINARY NOT NULL CHECK (typeof(name)='text' AND instr(name,char(0))=0 AND length(CAST(name AS BLOB)) BETWEEN 1 AND 128),
  version INTEGER NOT NULL CHECK (typeof(version)='integer' AND version>=1),
  payload_json TEXT COLLATE BINARY NOT NULL CHECK (typeof(payload_json)='text' AND instr(payload_json,char(0))=0 AND length(CAST(payload_json AS BLOB)) BETWEEN 1 AND 65536),
  recorded_at INTEGER NOT NULL CHECK (typeof(recorded_at)='integer' AND recorded_at>=0),
  UNIQUE (workflow,event_id)
);
CREATE TABLE "__mistri_workflow_action" (
  seq INTEGER PRIMARY KEY,
  instance_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(instance_id)='text' AND instr(instance_id,char(0))=0 AND length(CAST(instance_id AS BLOB)) BETWEEN 1 AND 36) REFERENCES "__mistri_workflow_instance" (id) ON DELETE CASCADE,
  action TEXT NOT NULL CHECK (action IN ('cancel','retry')),
  operator TEXT COLLATE BINARY NOT NULL CHECK (typeof(operator)='text' AND instr(operator,char(0))=0 AND length(CAST(operator AS BLOB)) BETWEEN 1 AND 128),
  at INTEGER NOT NULL CHECK (typeof(at)='integer' AND at>=0)
);
CREATE UNIQUE INDEX "__mistri_workflow_live" ON "__mistri_workflow_instance" (workflow,key) WHERE state IN ('running','waiting');
CREATE INDEX "__mistri_workflow_waiting" ON "__mistri_workflow_instance" (workflow,wait_event) WHERE state='waiting';
CREATE INDEX "__mistri_workflow_signal_event" ON "__mistri_workflow_signal" (workflow,name,version,seq);
CREATE INDEX "__mistri_workflow_action_instance" ON "__mistri_workflow_action" (instance_id,seq);
INSERT INTO "__mistri_workflow_meta" ("singleton", "version") VALUES (1, 1);
